<?php use Luna\Core\Csrf;use Luna\Core\View;$token=View::e(Csrf::token());?>
<div class="page-intro"><div><span class="eyebrow">Omnichannel</span><h1>Hub e-commerce</h1><p>WooCommerce, Shopify, Amazon ed eBay con code, retry e ordini idempotenti.</p></div><div class="intro-actions"><a class="button" href="/r/ecommerce-channels/create">Configura canale</a><form method="post" action="/operations/ecommerce/process"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Elabora coda</button></form></div></div>
<section class="card"><div class="card-header"><div><h2>Canali</h2><p>Le credenziali sono riferimenti ENV JSON, mai salvate in chiaro.</p></div></div><div class="table-wrap"><table><thead><tr><th>Canale</th><th>Piattaforma</th><th>Stato</th><th>Ultimo successo</th><th>Ultimo errore</th><th>Sincronizza</th></tr></thead><tbody><?php foreach($channels as $c):?><tr><td class="primary-cell"><?= View::e($c['name']) ?></td><td><?= View::e($c['platform']) ?></td><td><span class="badge status-<?= strtolower($c['status']) ?>"><?= View::e($c['status']) ?></span></td><td><?= View::date($c['last_success_at']??null) ?></td><td title="<?= View::e($c['last_error']??'') ?>"><?= View::e(mb_substr((string)($c['last_error']??''),0,70)) ?></td><td><form method="post" action="/operations/ecommerce/channels/<?= (int)$c['id'] ?>/enqueue" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><select name="operation"><option>PULL_ORDERS</option><option>PULL_PRODUCTS</option><option>PUSH_STOCK</option><option>PUSH_PRICES</option><option>ACK_ORDER</option></select><input type="number" name="product_id" placeholder="ID prodotto"><input type="number" name="ecommerce_order_id" placeholder="ID ordine"><button class="button">Accoda</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Ordini acquisiti</h2></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Canale</th><th>ID esterno</th><th>Cliente</th><th>Totale</th><th>Stato</th><th>Importazione</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?= View::date($o['order_date']) ?></td><td><?= View::e($o['channel_name']??$o['platform']) ?></td><td class="primary-cell"><?= View::e($o['external_order_id']) ?></td><td><?= View::e($o['customer_email']??'—') ?></td><td><?= View::money($o['total']) ?></td><td><?= View::e($o['status']) ?></td><td><span class="badge status-<?= strtolower($o['import_status']) ?>"><?= View::e($o['import_status']) ?></span></td><td><?php if(!$o['luna_document_id']):?><form method="post" action="/operations/ecommerce/orders/<?= (int)$o['id'] ?>/convert"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Crea ordine Luna</button></form><?php else:?><a class="button" href="/documents/orders/<?= (int)$o['luna_document_id'] ?>">Apri ordine</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><div><h2>Catalogo sincronizzato</h2><p>Lo SKU collega automaticamente il prodotto esterno all’anagrafica Luna2.</p></div></div><div class="table-wrap"><table><thead><tr><th>Canale</th><th>ID esterno</th><th>SKU</th><th>Prodotto</th><th>Prezzo</th><th>Disponibilità esterna</th><th>Prodotto Luna</th></tr></thead><tbody><?php foreach($catalog as $p):?><tr><td><?= View::e($p['channel_name']??$p['platform']) ?></td><td><?= View::e($p['external_product_id']) ?></td><td class="primary-cell"><?= View::e($p['sku']??'—') ?></td><td><?= View::e($p['name']) ?></td><td><?= $p['price']!==null?View::money($p['price']):'—' ?></td><td><?= View::e($p['quantity']??'—') ?></td><td><?= View::e($p['local_code']??'Non mappato') ?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Coda tecnica</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Canale</th><th>Operazione</th><th>Stato</th><th>Tentativi</th><th>Disponibile</th><th>Errore</th></tr></thead><tbody><?php foreach($queue as $q):?><tr><td><?= (int)$q['id'] ?></td><td><?= View::e($q['channel_name']) ?></td><td><?= View::e($q['operation']) ?></td><td><span class="badge status-<?= strtolower($q['status']) ?>"><?= View::e($q['status']) ?></span></td><td><?= (int)$q['attempts'] ?></td><td><?= View::date($q['available_at']) ?></td><td><?= View::e(mb_substr((string)($q['error_message']??''),0,90)) ?></td></tr><?php endforeach;?></tbody></table></div></section>
